import {ChatInput} from '@github-ui/copilot-chat/components/ChatInput'
import type {CopilotChatState} from '@github-ui/copilot-chat/utils/copilot-chat-reducer'
import type {
  CopilotChatPayload,
  CopilotChatReference,
  StarterEntry,
} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {copilotLocalStorage} from '@github-ui/copilot-chat/utils/copilot-local-storage'
import {CopilotChatProvider} from '@github-ui/copilot-chat/utils/CopilotChatContext'
import {useGetChatState} from '@github-ui/copilot-chat/utils/ObservableChatContext'
import {getStarterGroups} from '@github-ui/copilot-immersive-v1/components/NewConversation/starter-groups'
import {StarterGroupWithMenu} from '@github-ui/copilot-immersive-v1/components/NewConversation/StarterGroupWithMenu'
import {sendEvent} from '@github-ui/hydro-analytics'
import {relayEnvironmentWithMissingFieldHandlerForNode} from '@github-ui/relay-environment'
import {CommentIcon} from '@primer/octicons-react'
import {useCallback} from 'react'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {RelayEnvironmentProvider} from 'react-relay'

import styles from './CopilotChatInputPartial.module.css'

const environment = relayEnvironmentWithMissingFieldHandlerForNode()

export interface CopilotChatInputPartialProps extends CopilotChatPayload {
  searchWorkerFilePath: string
  /** for testing only */
  testReducerState?: CopilotChatState
}

export function CopilotChatInputPartial(props: CopilotChatInputPartialProps) {
  return (
    <RelayEnvironmentProvider environment={environment}>
      <CopilotChatProvider
        copilotChatPayload={props}
        mode="immersive"
        refs={[]}
        ssoOrganizations={[]} // TODO
        testReducerState={props.testReducerState}
        threadId={null}
        workerPath={props.searchWorkerFilePath}
      >
        <StandaloneInput />
      </CopilotChatProvider>
    </RelayEnvironmentProvider>
  )
}

function StandaloneInput() {
  const getChatState = useGetChatState()
  const handleSubmit = useCallback(
    async (message: string) => {
      const state = getChatState()
      sendEvent('dotcom_chat.activate', {
        target: 'DASHBOARD_ENTRYPOINT_SEND',
        mode: 'immersive',
        richInput: true,
      })
      sendMessage(message, state.currentReferences)
    },
    [getChatState],
  )

  const onStarterSelect = useCallback(
    (entry: StarterEntry) => {
      const state = getChatState()
      const currentUserLogin = state.currentUserLogin || ''
      const message = entry.message.replaceAll('$$USERNAME$$', currentUserLogin)
      sendEvent('dotcom_chat.activate', {
        target: 'DASHBOARD_STARTER_MENU_ITEM',
        mode: 'immersive',
        starterId: entry.id,
      })
      sendMessage(message)
    },
    [getChatState],
  )

  return (
    <div>
      <ChatInput
        className={styles.input}
        disableAutoFocus
        modes={[
          {
            name: 'Chat',
            supportsMCP: false,
            supportsAttachments: true,
            supportsModelSwitching: true,
            supportsSpaces: true,
            supportsAutocompletion: true,
            icon: <CommentIcon />,
            placeholder: 'How can I help you?',
          },
        ]}
        onSubmit={handleSubmit}
      />
      <ul className={styles.starters}>
        {getStarterGroups().map(group => (
          <StarterGroupWithMenu key={group.id} group={group} onEntrySelect={onStarterSelect} />
        ))}
      </ul>
    </div>
  )
}

function sendMessage(message: string, references?: CopilotChatReference[]) {
  copilotLocalStorage.setEntrypointMessage(message, references)
  document.querySelector('.application-main')?.classList.add('appMain--fadeOut')
  setTimeout(() => {
    window.location.href = `/copilot`
  }, 200)
}

try{ CopilotChatInputPartial.displayName ||= 'CopilotChatInputPartial' } catch {}
try{ StandaloneInput.displayName ||= 'StandaloneInput' } catch {}